function restore(){const q=new URLSearchParams(location.search);state.scope=q.get('scope')==='taichung'?'taichung':'taiwan';state.place=names().includes(q.get('place'))?q.get('place'):'all';state.q=(q.get('q')||'').slice(0,80);}
